+    static <T> T storedValue(String key, Supplier<T> build) {
+        try {
+            return build.get();
+        } catch (IllegalArgumentException invalid) {
+            throw new IllegalStateException(
+                    "stored learning JSON has an invalid value at key: " + key, invalid);
+        }
+    }
